(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,1322,(D,B,r)=>{B.exports=JSON.parse('[{"id":"дама-с-собачкой-1","text":"Говорили, что на набережной появилось новое лицо: дама с собачкой. Дмитрий Дмитрич Гуров, проживший в Ялте уже две недели и привыкший тут, тоже стал интересоваться новыми лицами.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-2","text":"Она засмеялась. Потом оба продолжали есть молча, как незнакомые; но после обеда пошли рядом - и начался шутливый, легкий разговор людей свободных, довольных, которым всё равно, куда бы ни идти, о чем ни говорить.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-3","text":"Прошла неделя после знакомства. Был праздничный день. В комнатах было душно, а на улицах вихрем носилась пыль, срывало шляпы. Весь день хотелось пить, и Гуров часто заходил в павильон и предлагал Анне Сергеевне то воды с сиропом, то мороженого.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-4","text":"Но тут всё та же несмелость, угловатость неопытной молодости, неловкое чувство; и было впечатление растерянности, как будто кто вдруг постучал в дверь.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-5","text":"В Ореанде сидели на скамье, недалеко от церкви, смотрели вниз на море и молчали. Ялта была едва видна сквозь утренний туман, на вершинах гор неподвижно стояли белые облака.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-6","text":"Почти каждый вечер попозже они уезжали куда-нибудь за город, в Ореанду или на водопад; и прогулка удавалась, впечатления неизменно всякий раз были прекрасны, величавы.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-7","text":"Дома в Москве уже всё было по-зимнему, топили печи, и по утрам, когда дети собирались в гимназию и пили чай, было темно, и няня ненадолго зажигала огонь.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-8","text":"Но прошло больше месяца, наступила глубокая зима, а в памяти всё было ясно, точно расстался он с Анной Сергеевной только вчера. И воспоминания разгорались всё сильнее.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-9","text":"Эти слова, такие обычные, почему-то вдруг возмутили Гурова, показались ему унизительными, нечистыми. Какие дикие нравы, какие лица! Что за бестолковые ночи, какие неинтересные, незаметные дни!","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-10","text":"Он соображал: сегодня день неприсутственный, и муж, вероятно, дома. Да и всё равно, было бы бестактно войти в дом и смутить. Если же послать записку, то она, пожалуй, попадет в руки мужу, и тогда всё можно испортить.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-11","text":"Вместе с Анной Сергеевной вошел и сел рядом молодой человек с небольшими бакенами, очень высокий, сутулый; он при каждом шаге покачивал головой и, казалось, постоянно кланялся.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-12","text":"Повыше, на площадке, два гимназиста курили и смотрели вниз, но Гурову было всё равно, он привлек к себе Анну Сергеевну и стал целовать ее лицо, щеки, руки.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-13","text":"И по себе он судил о других, не верил тому, что видел, и всегда предполагал, что у каждого человека под покровом тайны, как под покровом ночи, проходит его настоящая, самая интересная жизнь.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"дама-с-собачкой-14","text":"Он почувствовал сострадание к этой жизни, еще такой теплой и красивой, но, вероятно, уже близкой к тому, чтобы начать блекнуть и вянуть, как его жизнь.","author":"А. П. Чехов","work":"Дама с собачкой","url":"https://ru.wikisource.org/wiki/%D0%94%D0%B0%D0%BC%D0%B0_%D1%81_%D1%81%D0%BE%D0%B1%D0%B0%D1%87%D0%BA%D0%BE%D0%B9_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"муму-1","text":"В одной из отдаленных улиц Москвы, в сером доме с белыми колоннами, антресолью и покривившимся балконом, жила некогда барыня, вдова, окруженная многочисленною дворней.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-2","text":"Каморка запиралась на замок, напоминавший своим видом калач, только черный; ключ от этого замка Герасим всегда носил с собой на пояске. Он не любил, чтобы к нему ходили.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-3","text":"Глупо смеясь и ласково мыча, протягивал он ей пряничного петушка, с сусальным золотом на хвосте и крыльях. Она было хотела отказаться, но он насильно впихнул его ей прямо в руку, покачал головой, пошел прочь и, обернувшись, еще раз промычал ей что-то очень дружелюбное.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-4","text":"Читатель теперь легко сам поймет причину смущения, овладевшего дворецким Гаврилой после разговора с госпожой. \\"Госпожа, - думал он, посиживая у окна, - конечно, жалует Герасима (Гавриле хорошо это было известно, и оттого он сам ему потакал), всё же он существо бессловесное; не доложить же госпоже, что вот Герасим, мол, за Татьяной ухаживает.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-5","text":"Барыне что-то нездоровилось; она недолго занималась делами. Дворецкий возвратился к себе в комнату и созвал совет. Дело точно требовало особенного обсуждения.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-6","text":"Форейтор Антипка сказывал потом, что он сквозь щелку видел, как Герасим, сидя на кровати, приложив к щеке руку, тихо, мерно и только изредка мыча, пел, то есть покачивался, закрывал глаза и встряхивал головой, как ямщики или бурлаки, когда они затягивают свои заунывные песни.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-7","text":"Герасим глядел, глядел да как засмеется вдруг... Всю ночь он возился с ней, укладывал ее, обтирал и заснул наконец сам возле нее каким-то радостным и тихим сном.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-8","text":"В тот день она как-то счастливо встала; на картах ей вышло четыре валета: исполнение желаний (она всегда гадала по утрам), - и чай ей показался особенно вкусным, за что горничная получила на словах похвалу и деньгами гривенник.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-9","text":"Проходя через гостиную, дворецкий для порядка переставил колокольчик с одного стола на другой, втихомолочку высморкал в зале свой утиный нос и вышел в переднюю.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-10","text":"Весь следующий день Герасим не показывался, так что вместо его за водой должен был съездить кучер Потап, чем кучер Потап очень остался недоволен. Барыня спросила Гаврилу, исполнено ли ее приказание.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-11","text":"В течение дня Герасим раза два украдкой ходил к своей затворнице; когда же наступила ночь, он лег спать вместе с ней в каморке, а не на сеновале и только во втором часу вышел погулять с ней на чистом воздухе.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-12","text":"На следующее утро барыня проснулась довольно поздно. Гаврила ожидал ее пробуждения для того, чтобы дать приказ к решительному натиску на Герасимово убежище, а сам готовился выдержать сильную грозу.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-13","text":"Муму принялась есть с обычной своей вежливостью, едва прикасаясь мордочкой до кушанья. Герасим долго глядел на нее; две тяжелые слезы выкатились вдруг из его глаз: одна упала на крутой лобик собачки, другая - во щи.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"муму-14","text":"Дорогу он хорошо заметил еще тогда, когда его везли в Москву; деревня, из которой барыня его взяла, лежала всего в двадцати пяти верстах от шоссе. Он шел по нем с какой-то несокрушимой отвагой, с отчаянной и вместе радостной решимостью.","author":"И. С. Тургенев","work":"Муму","url":"https://ru.wikisource.org/wiki/%D0%9C%D1%83%D0%BC%D1%83_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"шинель-1","text":"В департаменте... но лучше не называть, в каком департаменте. Ничего нет сердитее всякого рода департаментов, полков, канцелярий и, словом, всякого рода должностных сословий.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-2","text":"Уж если так, пусть лучше будет он называться, как и отец его. Отец был Акакий, так пусть и сын будет Акакий\\". Таким образом и произошел Акакий Акакиевич.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-3","text":"Вряд ли где можно было найти человека, который так жил бы в своей должности. Мало сказать: он служил ревностно, - нет, он служил с любовью. Там, в этом переписыванье, ему виделся какой-то свой разнообразный и приятный мир.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-4","text":"Так протекала мирная жизнь человека, который с четырьмястами жалованья умел быть довольным своим жребием, и дотекла бы, может быть, до глубокой старости, если бы не было разных бедствий, рассыпанных на жизненной дороге не только титулярным, но даже тайным, действительным, надворным и всяким советникам, даже и тем, которые не дают никому советов, ни от кого не берут их сами.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-5","text":"Так как мы уже заикнулись про жену, то нужно будет и о ней сказать слова два; но, к сожалению, о ней не много было известно, разве только то, что у Петровича есть жена, носит даже чепчик, а не платок; но красотою, как кажется, она не могла похвастаться; по крайней мере, при встрече с нею одни только гвардейские солдаты заглядывали ей под чепчик, моргнувши усом и испустивши какой-то особый голос.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-6","text":"Вышед на улицу, Акакий Акакиевич был как во сне. \\"Этаково-то дело этакое, - говорил он сам себе, - я, право, и не думал, чтобы оно вышло того...- а потом, после некоторого молчания, прибавил: - Так вот как! наконец вот что вышло, а я, право, совсем и предполагать не мог, чтобы оно было этак\\".","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-7","text":"Еще половину можно бы найти: половина бы отыскалась; может быть, даже немножко и больше; но где взять другую половину?.. Но прежде читателю должно узнать, где взялась первая половина.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-8","text":"Куницы не купили, потому что была, точно, дорога; а вместо ее выбрали кошку, лучшую, какая только нашлась в лавке, кошку, которую издали можно было всегда принять за куницу.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-9","text":"Между тем Акакий Акакиевич шел в самом праздничном расположении всех чувств. Он чувствовал всякий миг минуты, что на плечах его новая шинель, и несколько раз даже усмехнулся от внутреннего удовольствия.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-10","text":"Остановился с любопытством перед освещенным окошком магазина посмотреть на картину, где изображена была какая-то красивая женщина, которая скидала с себя башмак, обнаживши, таким образом, всю ногу, очень недурную; а за спиной ее, из дверей другой комнаты, выставил голову какой-то мужчина с бакенбардами и красивой эспаньолкой под губой.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-11","text":"Чтобы как-нибудь не вздумал удерживать хозяин, он вышел потихоньку из комнаты, отыскал в передней шинель, которую не без сожаления увидел лежавшею на полу, стряхнул ее, снял с нее всякую пушинку, надел на плеча и опустился по лестнице на улицу.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-12","text":"Благодаря великодушному вспомоществованию петербургского климата болезнь пошла быстрее, чем можно было ожидать, и когда явился доктор, то он, пощупавши пульс, ничего не нашелся сделать, как только прописать припарку, единственно уже для того, чтобы больной не остался без благодетельной помощи медицины; а впрочем, тут же объявил ему чрез полтора суток непременный капут.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-13","text":"Схвативши его за ворот, он вызвал своим криком двух других товарищей, которым поручил держать его, а сам полез только на одну минуту за сапог, чтобы вытащить оттуда тавлинку с табаком, освежить на время шесть раз на веку примороженный нос свой; но табак, верно, был такого рода, которого не мог вынести даже и мертвец.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"шинель-14","text":"Итак, значительное лицо сошел с лестницы, сел в сани и сказал кучеру: \\"К Каролине Ивановне\\", - а сам, закутавшись весьма роскошно в теплую шинель, оставался в том приятном положении, лучше которого и не выдумаешь для русского человека, то есть когда сам ни о чем не думаешь, а между тем мысли сами лезут в голову, одна другой приятнее, не давая даже труда гоняться за ними и искать их.","author":"Н. В. Гоголь","work":"Шинель","url":"https://ru.wikisource.org/wiki/%D0%A8%D0%B8%D0%BD%D0%B5%D0%BB%D1%8C_(%D0%93%D0%BE%D0%B3%D0%BE%D0%BB%D1%8C)%2F%D0%A1%D0%A1_1967_(%D0%A1%D0%9E)"},{"id":"капитанская-дочка-1","text":"Отец мой Андрей Петрович Гринев в молодости своей служил при графе Минихе и вышел в отставку премьер-майором в 17.. году. С тех пор жил он в своей Симбирской деревне, где и женился на девице Авдотье Васильевне Ю., дочери бедного тамошнего дворянина.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-2","text":"Наконец я сказал ему: \\"Ну, ну, Савельич! полно, помиримся, виноват; вижу сам, что виноват. Я вчера напроказил, а тебя напрасно обидел. Обещаюсь вперед вести себя умнее и слушаться тебя.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-3","text":"За ними простирались киргизские степи. Я погрузился в размышления, большею частию печальные. Гарнизонная жизнь мало имела для меня привлекательности. Я старался вообразить себе капитана Миронова, моего будущего начальника, и представлял его строгим, сердитым стариком, не знающим ничего, кроме своей службы, и готовым за всякую безделицу сажать меня под арест на хлеб и на воду.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-4","text":"Иван Игнатьич выслушал меня со вниманием, вытараща на меня свой единственный глаз. \\"Вы изволите говорить, - сказал он мне, - что хотите Алексея Иваныча заколоть, и желаете, чтоб я при том был свидетелем?","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-5","text":"С Василисой Егоровной и с ее мужем я еще не объяснялся; но предложение мое не должно было их удивить. Ни я, ни Марья Ивановна не старались скрывать от них свои чувства, и мы заранее были уж уверены в их согласии.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-6","text":"Посланы были к ним лазутчики. Юлай, крещеный калмык, сделал коменданту важное донесение. Показания урядника, по словам Юлая, были ложны: по возвращении своем лукавый казак объявил своим товарищам, что он был у бунтовщиков, представлялся самому их предводителю, который допустил его к своей руке и долго с ним разговаривал.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-7","text":"Пугачев сидел в креслах на крыльце комендантского дома. На нем был красный казацкий кафтан, обшитый галунами. Высокая соболья шапка с золотыми кистями была надвинута на его сверкающие глаза.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-8","text":"Я оставил Пугачева и вышел на улицу. Ночь была тихая и морозная. Месяц и звезды ярко сияли, освещая площадь и виселицу. В крепости всё было спокойно и темно.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-9","text":"Не стану описывать оренбургскую осаду, которая принадлежит истории, а не семейственным запискам. Скажу вкратце, что сия осада по неосторожности местного начальства была гибельна для жителей, которые претерпели голод и всевозможные бедствия.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-10","text":"\\"Стой! стой!\\" - раздался голос, слишком мне знакомый, - и я увидел Савельича, бежавшего нам навстречу. Пугачев велел остановиться. \\"Батюшка, Петр Андреич! - кричал дядька. - Не покинь меня на старости лет посреди этих мошен...\\" - \\"А, старый хрыч! - сказал ему Пугачев. - Опять бог дал свидеться.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-11","text":"Через пять минут мы пришли к домику, ярко освещенному. Вахмистр оставил меня при карауле и пошел обо мне доложить. Он тотчас же воротился, объявив мне, что его высокоблагородию некогда меня принять, а что он велел отвести меня в острог, а хозяюшку к себе привести.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-12","text":"Я изумился его перемене. Он был ужасно худ и бледен. Волоса его, недавно черные как смоль, совершенно поседели; длинная борода была всклокочена. Он повторил обвинения свои слабым, но смелым голосом.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-13","text":"Луна зашла за облако. Плывучий призрак сделался еще неяснее. Он был от меня уже близко, и я всё еще не мог различить. \\"Что бы это было, - говорили гребцы. - Парус не парус, мачты не мачты...\\" - Вдруг луна вышла из-за облака и озарила зрелище ужасное.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"капитанская-дочка-14","text":"Не стану описывать нашего похода и окончания Пугачевской войны. Мы проходили через селения, разоренные Пугачевым, и поневоле отбирали у бедных жителей то, что оставлено было им разбойниками.","author":"А. С. Пушкин","work":"Капитанская дочка","url":"https://ru.wikisource.org/wiki/%D0%9A%D0%B0%D0%BF%D0%B8%D1%82%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%B4%D0%BE%D1%87%D0%BA%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)"},{"id":"станционный-смотритель-1","text":"Кто не проклинал станционных смотрителей, кто с ними не бранивался? Кто, в минуту гнева, не требовал от них роковой книги, дабы вписать в оную свою бесполезную жалобу на притеснение, грубость и неисправность?","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-2","text":"В дождь и слякоть принужден он бегать по дворам; в бурю, в крещенский мороз уходит он в сени, чтоб только на минуту отдохнуть от крика и толчков раздраженного постояльца.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-3","text":"Столь же долго не мог я привыкнуть и к тому, чтоб разборчивый холоп обносил меня блюдом на губернаторском обеде. Ныне то и другое кажется мне в порядке вещей.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-4","text":"Наконец представлено возвращение его к отцу; добрый старик в том же колпаке и шлафорке выбегает к нему на встречу: блудный сын стоит на коленах; в перспективе повар убивает упитанного тельца, и старший брат вопрошает слуг о причине таковой радости.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-5","text":"Смотритель спал под тулупом; мой приезд разбудил его; он привстал... Это был точно Самсон Вырин; но как он постарел! Покамест собирался он переписать мою подорожную, я смотрел на его седину, на глубокие морщины давно небритого лица, на сгорбленную спину - и не мог надивиться, как три или четыре года могли превратить бодрого мужчину в хилого старика.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-6","text":"Бывало барин, какой бы сердитый ни был, при ней утихает и милостиво со мною разговаривает. Поверите ль, сударь: курьеры, фельд-егеря с нею по получасу заговаривались.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-7","text":"На другой день гусару стало хуже. Человек его поехал верхом в город за лекарем. Дуня обвязала ему голову платком, намоченным уксусом, и села с своим шитьем у его кровати.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-8","text":"Дуня стояла в недоумении... \\"Чего же ты боишься?\\" сказал ей отец; \\"ведь его высокоблагородие не волк и тебя не съест: прокатись-ка до церкви\\". Дуня села в кибитку подле гусара, слуга вскочил на облучок, ямщик свистнул и лошади поскакали.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-9","text":"В мучительном волнении ожидал он возвращения тройки, на которой он отпустил ее. Ямщик не возвращался. Наконец к вечеру приехал он один и хмелен, с убийственным известием: \\"Дуня с той станции отправилась далее с гусаром\\".","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-10","text":"Минский взглянул на него быстро, вспыхнул, взял его за руку, повел в кабинет и запер за собою дверь. \\"Ваше высокоблагородие!\\" продолжал старик, \\"что с возу упало, то пропало; отдайте мне, по крайней мере, бедную мою Дуню.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-11","text":"Для сего, дни через два, воротился он к Минскому; но военный лакей сказал ему сурово, что барин никого не принимает, грудью вытеснил его из передней, и хлопнул двери ему под нос.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-12","text":"Но смотритель, не слушая, шел далее. Две первые комнаты были темны, в третьей был огонь. Он подошел к растворенной двери и остановился. В комнате прекрасно-убранной Минский сидел в задумчивости.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-13","text":"\\"Вот уже третий год, заключил он, как живу я без Дуни, и как об ней нет ни слуху, ни духу. Жива ли, нет ли, бог ее ведает. Всяко случается. Не ее первую, не ее последнюю сманил проезжий повеса, а там подержал, да и бросил.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"станционный-смотритель-14","text":"Мне стало жаль моей напрасной поездки и семи рублей, издержанных даром. \\"От чего ж он умер?\\" спросил я пивоварову жену. - \\"Спился, батюшка\\", отвечала она. - \\"А где его похоронили?\\" - \\"За околицей, подле покойной хозяйки его\\". - \\"Нельзя ли довести меня до его могилы?\\" - \\"Почему же нельзя.","author":"А. С. Пушкин","work":"Станционный смотритель","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%BE%D0%B2%D0%B5%D1%81%D1%82%D0%B8_%D0%BF%D0%BE%D0%BA%D0%BE%D0%B9%D0%BD%D0%BE%D0%B3%D0%BE_%D0%98%D0%B2%D0%B0%D0%BD%D0%B0_%D0%9F%D0%B5%D1%82%D1%80%D0%BE%D0%B2%D0%B8%D1%87%D0%B0_%D0%91%D0%B5%D0%BB%D0%BA%D0%B8%D0%BD%D0%B0_(%D0%9F%D1%83%D1%88%D0%BA%D0%B8%D0%BD)%2F%D0%A1%D1%82%D0%B0%D0%BD%D1%86%D0%B8%D0%BE%D0%BD%D0%BD%D1%8B%D0%B9_%D1%81%D0%BC%D0%BE%D1%82%D1%80%D0%B8%D1%82%D0%B5%D0%BB%D1%8C"},{"id":"анна-каренина-1","text":"Все смешалось в доме Облонских. Жена узнала, что муж был в связи с бывшею в их доме француженкою-гувернанткой, и объявила мужу, что не может жить с ним в одном доме.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-2","text":"Она, эта вечно озабоченная, и хлопотливая, и недалекая, какою он считал ее, Долли, неподвижно сидела с запиской в руке и с выражением ужаса, отчаяния и гнева смотрела на него.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-3","text":"\\"Там видно будет\\", - сказал себе Степан Аркадьич и, встав, надел серый халат на голубой шелковой подкладке, закинул кисти узлом и, вдоволь забрав воздуха в свой широкий грудной ящик, привычным бодрым шагом вывернутых ног, так легко носивших его полное тело, подошел к окну, поднял стору и громко позвонил.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-4","text":"А иметь взгляды ему, жившему в известном обществе, при потребности некоторой деятельности мысли, развивающейся обыкновенно в лета зрелости, было так же необходимо, как иметь шляпу.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-5","text":"Девочка знала, что между отцом и матерью была ссора, и что мать не могла быть весела, и что отец должен знать это, и что он притворяется, спрашивая об этом так легко.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-6","text":"Увидав мужа, она опустила руки в ящик шифоньерки, будто отыскивая что-то, и оглянулась на него, только когда он совсем вплоть подошел к ней. Но лицо ее, которому она хотела придать строгое и решительное выражение, выражало потерянность и страдание.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-7","text":"\\"Ага! Стива! Облонский! Вот и он!\\" - почти всегда с радостною улыбкой говорили, встречаясь с ним. Если и случалось иногда, что после разговора с ним оказывалось, что ничего особенно радостного не случилось, - на другой день, на третий опять точно так же все радовались при встрече с ним.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-8","text":"Каждому казалось, что та жизнь, которую он сам ведет, есть одна настоящая жизнь, а которую ведет приятель - есть только призрак. Облонский не мог удержать легкой насмешливой улыбки при виде Левина.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-9","text":"Он вместе готовился и вместе поступил в университет с молодым князем Щербацким, братом Долли и Кити. В это время Левин часто бывал в доме Щербацких и влюбился в дом Щербацких.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-10","text":"Кроме того, его прежние отношения к Кити - отношения взрослого к ребенку, вследствие дружбы с ее братом, - казались ему еще новою преградой для любви.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-11","text":"Профессор с досадой и как будто умственною болью от перерыва оглянулся на странного вопрошателя, похожего более на бурлака, чем на философа, и перенес глаза на Сергея Ивановича, как бы спрашивая: что ж тут говорить?","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-12","text":"Пробыв в Москве, как в чаду, два месяца, почти каждый день видаясь с Кити в свете, куда он стал ездить, чтобы встречаться с нею, Левин внезапно решил, что этого не может быть, и уехал в деревню.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-13","text":"Получив от лакея Сергея Ивановича адрес брата, Левин тотчас же собрался ехать к нему, но, обдумав, решил отложить свою поездку до вечера. Прежде всего, для того чтобы иметь душевное спокойствие, надо было решить то дело, для которого он приехал в Москву.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"анна-каренина-14","text":"На льду собирались в этот день недели и в эту пору дня люди одного кружка, все знакомые между собою. Были тут и мастера кататься, щеголявшие искусством, и учившиеся за креслами, с робкими неловкими движениями, и мальчики, и старые люди, катавшиеся для гигиенических целей; все казались Левину избранными счастливцами, потому что они были тут, вблизи от нее.","author":"Л. Н. Толстой","work":"Анна Каренина","url":"https://ru.wikisource.org/wiki/%D0%90%D0%BD%D0%BD%D0%B0_%D0%9A%D0%B0%D1%80%D0%B5%D0%BD%D0%B8%D0%BD%D0%B0_(%D0%A2%D0%BE%D0%BB%D1%81%D1%82%D0%BE%D0%B9)"},{"id":"отцы-и-дети-1","text":"Слуга, в котором все: и бирюзовая сережка в ухе, и напомаженные разноцветные волосы, и учтивые телодвижения, словом, все изобличало человека новейшего, усовершенствованного поколения, посмотрел снисходительно вдоль дороги и ответствовал: \\"Никак нет-с, не видать\\".","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-2","text":"Супруги жили очень хорошо и тихо: они почти никогда не расставались, читали вместе, играли в четыре руки на фортепьяно, пели дуэты; она сажала цветы и наблюдала за птичьим двором, он изредка ездил на охоту и занимался хозяйством, а Аркадий рос да рос - тоже хорошо и тихо.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-3","text":"Зовут его Николаем Петровичем Кирсановым. У него в пятнадцати верстах от постоялого дворика хорошее имение в двести душ, или, как он выражается с тех пор, как размежевался с крестьянами и завел \\"ферму\\", - в две тысячи десятин земли.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-4","text":"Десять лет прошло как сон. В 47-м году жена Кирсанова скончалась. Он едва вынес этот удар, поседел в несколько недель; собрался было за границу, чтобы хотя немного рассеяться... но тут настал 48-й год.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-5","text":"\\"Нет, - подумал Аркадий, - небогатый край этот, не поражает он ни довольством, ни трудолюбием; нельзя, нельзя ему так остаться, преобразования необходимы... но как их исполнить, как приступить?..\\"","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-6","text":"Аркадий глядел, глядел, и, понемногу ослабевая, исчезали его размышления... Он сбросил с себя шинель и так весело, таким молоденьким мальчиком посмотрел на отца, что тот опять его обнял.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-7","text":"Он без нужды растягивал свою речь, избегал слова \\"папаша\\" и даже раз заменил его словом \\"отец\\", произнесенным, правда, сквозь зубы; с излишнею развязностью налил себе в стакан гораздо больше вина, чем самому хотелось, и выпил все вино.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-8","text":"Представилась ли ему в это мгновение неизбежная странность будущих отношений между им и сыном, сознавал ли он, что едва ли не большее бы уважение оказал ему Аркадий, если б он вовсе не касался этого дела, упрекал ли он самого себя в слабости - сказать трудно; все эти чувства были в нем, но в виде ощущений - и то неясных; а с лица не сходила краска, и сердце билось.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-9","text":"В то время в петербургском свете изредка появлялась женщина, которую не забыли до сих пор, княгиня Р. У ней был благовоспитанный и приличный, но глуповатый муж и не было детей.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-10","text":"Он вышел в отставку, несмотря на просьбы приятелей, на увещания начальников, и отправился вслед за княгиней; года четыре провел он в чужих краях, то гоняясь за нею, то с намерением теряя ее из виду; он стыдился самого себя, он негодовал на свое малодушие... но ничто не помогало.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-11","text":"Вместо ответа Николай Петрович обнял его; но полтора года прошло после этого разговора, прежде чем Павел Петрович решился осуществить свое намерение. Зато, поселившись однажды в деревне, он уже не покидал ее даже и в те три зимы, которые Николай Петрович провел в Петербурге с сыном.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-12","text":"В ней пахло недавно выкрашенным полом, ромашкой и мелиссой. Вдоль стен стояли стулья с задками в виде лир; они были куплены еще покойником генералом в Польше, во время похода; в одном углу возвышалась кроватка под кисейным пологом, рядом с кованым сундуком с круглою крышкой.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-13","text":"В одно утро Арина явилась к нему в кабинет и, по обыкновению, низко поклонившись, спросила его, не может ли он помочь ее дочке, которой искра из печки попала в глаз.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"отцы-и-дети-14","text":"Прошло около двух недель. Жизнь в Марьине текла своим порядком: Аркадий сибаритствовал, Базаров работал. Все в доме привыкли к нему, к его небрежным манерам, к его немногосложным и отрывочным речам.","author":"И. С. Тургенев","work":"Отцы и дети","url":"https://ru.wikisource.org/wiki/%D0%9E%D1%82%D1%86%D1%8B_%D0%B8_%D0%B4%D0%B5%D1%82%D0%B8_(%D0%A2%D1%83%D1%80%D0%B3%D0%B5%D0%BD%D0%B5%D0%B2)"},{"id":"палата-6-1","text":"В больничном дворе стоит небольшой флигель, окруженный целым лесом репейника, крапивы и дикой конопли. Крыша на нем ржавая, труба наполовину обвалилась, ступеньки у крыльца сгнили и поросли травой, а от штукатурки остались одни только следы.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-2","text":"Гримасы его странны и болезненны, но тонкие черты, положенные на его лицо глубоким искренним страданием, разумны и интеллигентны, и в глазах теплый, здоровый блеск.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-3","text":"В больничном дворе стоит небольшой флигель, окруженный целым лесом репейника, крапивы и дикой конопли. Крыша на нем ржавая, труба наполовину обвалилась, ступеньки у крыльца сгнили и поросли травой, а от штукатурки остались одни только следы.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-4","text":"Гримасы его странны и болезненны, но тонкие черты, положенные на его лицо глубоким искренним страданием, разумны и интеллигентны, и в глазах теплый, здоровый блеск.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-5","text":"Он не спал все ночи напролет, ожидая ареста, но громко храпел и вздыхал, как сонный, чтобы хозяйке казалось, что он спит; ведь если не спит, то, значит, его мучают угрызения совести - какая улика!","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-6","text":"Только время на соблюдение кое-каких формальностей, за которые судье платят жалованье, а затем - всё кончено. Ищи потом справедливости и защиты в этом маленьком, грязном городишке, за двести верст от железной дороги!","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-7","text":"Иногда он подходит к окну и, обернувшись к товарищам спиной, надевает себе что-то на грудь и смотрит, нагнув голову; если в это время подойти к нему, то он сконфузится и сорвет что-то с груди.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-8","text":"Это было похоже на то, как один пустынник хотел вырубить себе местечко в девственном лесу; чем усерднее он работал топором, тем гуще и сильнее разрастался лес.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-9","text":"В городе отлично знали про эти беспорядки и даже преувеличивали их, но относились к ним спокойно; одни оправдывали их тем, что в больницу ложатся только мещане и мужики, которые не могут быть недовольны, так как дома живут гораздо хуже, чем в больнице; не рябчиками же их кормить!","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-10","text":"Лицо суровое, покрыто синими жилками, глаза маленькие, нос красный. При высоком росте и широких плечах у него громадные руки и ноги; кажется, хватит кулаком - дух вон.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-11","text":"Да и к чему мешать людям умирать, если смерть есть нормальный и законный конец каждого? Что из того, если какой-нибудь торгаш или чиновник проживет лишних пять, десять лет?","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-12","text":"Михаил Аверьяныч уважает и любит Андрея Ефимыча за образованность и благородство души, к прочим же обывателям относится свысока, как к своим подчиненным.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-13","text":"Болезненность и смертность всё те же. Сумасшедшим устраивают балы и спектакли, а на волю их все-таки не выпускают. Значит, всё вздор и суета, и разницы между лучшею венскою клиникой и моею больницей, в сущности, нет никакой\\".","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"палата-6-14","text":"\\"Но что же? - спрашивает себя Андрей Ефимыч, открывая глаза. - Что же из этого? И антисептика, и Кох, и Пастер, а сущность дела нисколько не изменилась.","author":"А. П. Чехов","work":"Палата № 6","url":"https://ru.wikisource.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D0%B0_%E2%84%96_6_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-1","text":"На самом краю села Мироносицкого, в сарае старосты Прокофия расположились на ночлег запоздавшие охотники. Их было только двое: ветеринарный врач Иван Иваныч и учитель гимназии Буркин.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-2","text":"Рассказывали разные истории. Между прочим говорили о том, что жена старосты, Мавра, женщина здоровая и не глупая, во всю свою жизнь нигде не была дальше своего родного села, никогда не видела ни города, ни железной дороги, а в последние десять лет всё сидела за печью и только по ночам выходила на улицу.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-3","text":"А на педагогических советах он просто угнетал нас своею осторожностью, мнительностью и своими чисто футлярными соображениями насчёт того, что вот-де в мужской и женской гимназиях молодёжь ведёт себя дурно, очень шумит в классах, - ах, как бы не дошло до начальства, ах, как бы чего не вышло, - и что если б из второго класса исключить Петрова, а из четвёртого - Егорова, то было бы очень хорошо.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-4","text":"Мы, учителя, боялись его. И даже директор боялся. Вот подите же, наши учителя народ всё мыслящий, глубоко порядочный, воспитанный на Тургеневе и Щедрине, однако же этот человечек, ходивший всегда в калошах и с зонтиком, держал в руках всю гимназию целых пятнадцать лет!","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-5","text":"Спальня у Беликова была маленькая, точно ящик, кровать была с пологом. Ложась спать, он укрывался с головой; было жарко, душно, в закрытые двери стучался ветер, в печке гудело; слышались вздохи из кухни, вздохи зловещие...","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-6","text":"У хохлов тыквы называются кабаками, а кабаки шинками, и варят у них борщ с красненькими и с синенькими \\"такой вкусный, такой вкусный, что просто - ужас!\\"","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-7","text":"Директорша, инспекторша и все наши гимназические дамы ожили, даже похорошели, точно вдруг увидели цель жизни. Директорша берёт в театре ложу, и смотрим - в её ложе сидит Варенька с этаким веером, сияющая, счастливая, и рядом с ней Беликов, маленький, скрюченный, точно его из дому клещами вытащили.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-8","text":"А дома, как кто посторонний, так и перепалка. Такая жизнь, вероятно, наскучила, хотелось своего угла, да и возраст принять во внимание; тут уж перебирать некогда, выйдешь за кого угодно, даже за учителя греческого языка.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-9","text":"Теперь слушайте, что дальше. Какой-то проказник нарисовал карикатуру: идёт Беликов в калошах, в подсученных брюках, под зонтом, и с ним под руку Варенька; внизу подпись: \\"влюблённый антропос\\".","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-10","text":"На другой день он всё время нервно потирал руки и вздрагивал, и было видно по лицу, что ему нехорошо. И с занятий ушёл, что случилось с ним первый раз в жизни.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-11","text":"Но как раз в то время, когда он катился по лестнице, вошла Варенька и с нею две дамы; они стояли внизу и глядели - и для Беликова это было ужаснее всего.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-12","text":"Дня через три пришёл ко мне Афанасий и спросил, не надо ли послать за доктором, так как-де с барином что-то делается. Я пошёл к Беликову. Он лежал под пологом, укрытый одеялом, и молчал; спросишь его, а он только да или нет - и больше ни звука.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-13","text":"Вернулись мы с кладбища в добром расположении. Но прошло не больше недели, и жизнь потекла по-прежнему, такая же суровая, утомительная, бестолковая, жизнь, не запрещённая циркулярно, но и не разрешённая вполне; не стало лучше.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"},{"id":"человек-в-футляре-14","text":"Когда в лунную ночь видишь широкую сельскую улицу с её избами, стогами, уснувшими ивами, то на душе становится тихо; в этом своём покое, укрывшись в ночных тенях от трудов, забот и горя, она кротка, печальна, прекрасна, и кажется, что и звёзды смотрят на неё ласково и с умилением и что зла уже нет на земле и всё благополучно.","author":"А. П. Чехов","work":"Человек в футляре","url":"https://ru.wikisource.org/wiki/%D0%A7%D0%B5%D0%BB%D0%BE%D0%B2%D0%B5%D0%BA_%D0%B2_%D1%84%D1%83%D1%82%D0%BB%D1%8F%D1%80%D0%B5_(%D0%A7%D0%B5%D1%85%D0%BE%D0%B2)"}]')}]);